-- 4. CHAMADOS (Imagens JPEG 480px via DBMS_LOB.WRITEAPPEND)
DECLARE
    v_blob BLOB;
    PROCEDURE append_hex(p_hex VARCHAR2) IS
        v_raw RAW(2000) := HEXTORAW(p_hex);
    BEGIN
        DBMS_LOB.WRITEAPPEND(v_blob, UTL_RAW.LENGTH(v_raw), v_raw);
    END;
BEGIN
